BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Clearly trivial threshold definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does the term ''clearly trivial'' mean when applied to audit misstatements?', '["Misstatements that are inconsequential both individually and in the aggregate", "Misstatements below the performance materiality threshold", "Misstatements that management has agreed to correct", "Misstatements that do not affect the income statement"]'::jsonb, 0, 'AU-C 450.A2 defines clearly trivial as a threshold below which misstatements would be inconsequential individually and in the aggregate, whether judged by size, nature, or circumstances. This is significantly lower than materiality. Unlike performance materiality, which reduces the probability that aggregate uncorrected misstatements exceed materiality, clearly trivial is a floor below which tracking is unnecessary.', 'easy', 1),

-- Q2: medium / L2 — Management representation letter on uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the completion phase of the audit of Pinnacle Construction, the auditor requests specific representations in the management representation letter. Under AU-C 580, what must management represent regarding uncorrected misstatements?', '["That all misstatements identified during the audit have been corrected in the financial statements", "That the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "That management was not aware of any misstatements prior to the audit", "That the auditor is responsible for determining which misstatements to correct"]'::jsonb, 1, 'AU-C 580.15 requires management to represent that it believes the effects of uncorrected misstatements aggregated by the auditor are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items is included with the letter. This differs from stating all misstatements were corrected, since some may remain uncorrected by management''s choice.', 'medium', 2),

-- Q3: medium / L3 — Prior-period misstatement effect on current period
(1, 'Misstatements and Control Deficiencies', 'While auditing Glenview Technologies for the year ended December 31, 2025, the auditor discovers a $45,000 depreciation error originating in 2023 that overstates current net fixed assets. Under AU-C 450, the auditor should:', '["Ignore the misstatement since it originated in a previously audited period", "Report the misstatement to the prior-period auditor only", "Evaluate the effect of the uncorrected misstatement on both the current and prior-period financial statements", "Require management to restate all prior-period financial statements before issuing the current opinion"]'::jsonb, 2, 'AU-C 450.10 requires the auditor to evaluate uncorrected misstatements, including those arising in prior periods, for their effect on the current-period financial statements. The cumulative effect of the prior-period error on current balances must be considered. Simply ignoring it because it originated in a prior period would be incorrect, as the misstatement continues to affect the current balance sheet.', 'medium', 3),

-- Q4: medium / L3 — Qualitative factors in misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'The auditor of Sterling Financial identifies a $12,000 misstatement in officer compensation disclosures, well below the $200,000 materiality level. However, the misstatement conceals a related-party transaction. Under AU-C 450, the auditor should:', '["Disregard the misstatement because it is quantitatively immaterial", "Evaluate only whether the misstatement affects the income statement", "Treat the misstatement as clearly trivial given its small dollar amount", "Consider the qualitative characteristics of the misstatement, including whether it involves related parties"]'::jsonb, 3, 'AU-C 450.11 requires auditors to consider both quantitative and qualitative factors when evaluating misstatements. A misstatement that is quantitatively small may still be material if it involves concealment, related-party transactions, or management integrity concerns. Dismissing it solely based on its dollar amount relative to materiality would be inappropriate because the qualitative nature—concealing a related-party transaction—could make it material to users.', 'medium', 3),

-- Q5: medium / L3 — IT control deficiency impact breadth
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Insurance, the auditor discovers that the IT administrator has unrestricted access to both the production database and the change management system, with no compensating review. Under AU-C 265, the auditor should evaluate this deficiency by considering:', '["The number of financial statement line items and processes that rely on the IT system", "Only the transactions that the IT administrator personally processed", "Whether the deficiency has resulted in a known misstatement in the current year", "The IT administrator''s years of experience and professional certifications"]'::jsonb, 0, 'AU-C 265.A10 directs auditors to consider the breadth of impact when evaluating IT control deficiencies. An IT administrator with unrestricted access to production and change management affects all processes relying on that system, potentially impacting multiple financial statement assertions. Limiting the evaluation to only transactions personally processed would understate the severity, since the deficiency creates a pervasive risk across all IT-dependent processes.', 'medium', 3),

-- Q6: hard / L4 — Rollover vs iron curtain approach
(1, 'Misstatements and Control Deficiencies', 'Cascade Energy has a $75,000 uncorrected overstatement of revenue recognized in the prior year that reverses in the current year. Current-year materiality is $100,000. Under the rollover approach, the current-year income statement shows a $75,000 understatement. The auditor should conclude that:', '["The current-year income statement is materially correct because the balance sheet effect nets to zero", "Both the rollover and iron curtain methods should be considered when evaluating the effect on the current-year financial statements", "The current-year misstatement is clearly trivial because it reversed naturally", "Only the balance sheet effect matters since the income statement is self-correcting"]'::jsonb, 1, 'AU-C 450.A16 and SAB No. 108 indicate auditors should consider both the rollover approach (current-year income statement effect) and the iron curtain approach (cumulative balance sheet effect). Relying solely on one method may fail to capture the full impact. Concluding the misstatement is trivial because it reversed would ignore the $75,000 current-year income statement understatement, which approaches the $100,000 materiality threshold.', 'hard', 4),

-- Q7: easy / L1 — Summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of the summary of uncorrected misstatements that an auditor prepares during an audit?', '["A list of all adjusting journal entries management posted during the year", "A compilation of errors found in the prior-year audit", "An accumulation of identified misstatements that management has not corrected, communicated for management''s consideration", "A report of control deficiencies sent to those charged with governance"]'::jsonb, 2, 'Under AU-C 450.05, the auditor accumulates misstatements identified during the audit other than those that are clearly trivial. This summary of uncorrected misstatements is communicated to management with a request to correct them. It is distinct from a report on control deficiencies, which is governed by AU-C 265 and addresses weaknesses in internal control rather than specific financial statement errors.', 'easy', 1),

-- Q8: medium / L2 — Control deviation vs control deficiency
(1, 'Misstatements and Control Deficiencies', 'During testing of the accounts payable approval process at Morrison Retail, the auditor finds that 3 of 40 invoices lack a required supervisory signature. Under auditing standards, the auditor must distinguish between:', '["Material weaknesses and significant deficiencies only", "Factual misstatements and projected misstatements only", "Fraud risk factors and inherent risk factors only", "A control deviation, which is a failure to operate a control, and a control deficiency, which is a design or operation flaw"]'::jsonb, 3, 'AU-C 265.06 defines a control deficiency as existing when a control''s design or operation does not allow timely prevention or detection of misstatements. A control deviation is a specific instance where the control failed to operate as designed. The 3 missing signatures are deviations. The auditor evaluates whether these deviations indicate a broader deficiency in the control''s design or operating effectiveness rather than isolated lapses.', 'medium', 2),

-- Q9: easy / L1 — Pervasive misstatement definition
(1, 'Misstatements and Control Deficiencies', 'In auditing, what does the term ''pervasive'' mean when describing the effect of misstatements on financial statements?', '["The misstatements affect numerous accounts, represent a substantial portion of the statements, or affect disclosures fundamental to users'' understanding", "The misstatements exceed performance materiality by more than 50 percent", "The misstatements were intentionally caused by management", "The misstatements occurred in every quarter of the fiscal year"]'::jsonb, 0, 'AU-C 705.06 defines pervasive effects as those not confined to specific elements or accounts, that represent a substantial proportion of the financial statements, or fundamentally affect disclosures. Pervasiveness is a qualitative concept about the breadth and depth of impact, not simply a quantitative threshold. A misstatement limited to one account balance would generally not be pervasive regardless of its dollar amount.', 'easy', 1),

-- Q10: hard / L4 — Subsequent discovery of material weakness after report
(1, 'Misstatements and Control Deficiencies', 'After issuing an unmodified opinion on Meridian Healthcare''s December 31, 2025 financial statements, the auditor discovers in March 2026 that a material weakness existed in revenue recognition controls throughout the audit period. The auditor had not identified this weakness during fieldwork. Under professional standards, the auditor should evaluate whether:', '["The unmodified opinion should be withdrawn solely because a material weakness existed", "The audit procedures performed were sufficient to detect misstatements notwithstanding the material weakness, and whether additional procedures are needed", "The material weakness should be disclosed only in the next year''s audit report", "Management should issue corrected financial statements regardless of whether a misstatement occurred"]'::jsonb, 1, 'Under AU-C 585, when an auditor becomes aware of previously unknown information after report issuance, the auditor evaluates whether the audit opinion may need revision. The existence of a material weakness alone does not mandate withdrawal of the opinion; rather, the auditor assesses whether misstatements may exist that would have affected the report. Deferring communication to the next audit period would violate the timely communication requirements of AU-C 265.', 'hard', 4),

-- Q11: medium / L2 — Entity-level control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Atlas Manufacturing, the auditor learns that the board of directors has not met in over eight months and has not reviewed any quarterly financial reports. Under AU-C 265, this situation most likely represents:', '["A routine operational matter outside the scope of the financial audit", "A deficiency in application-level controls over specific transaction cycles", "A deficiency in entity-level controls that could have a pervasive effect on the financial statements", "A going concern issue requiring a modified audit opinion"]'::jsonb, 2, 'AU-C 265.A3 notes that deficiencies in entity-level controls—such as the control environment, monitoring activities, and governance oversight—may have a pervasive effect on the financial statements. An inactive board that fails to review financial reports represents a breakdown in oversight that affects all financial reporting. This differs from a transaction-level deficiency, which is confined to a specific process or cycle.', 'medium', 2),

-- Q12: medium / L3 — Estimation uncertainty and bias evaluation
(1, 'Misstatements and Control Deficiencies', 'Oakdale Insurance records a $2.4 million loss reserve for outstanding claims based on an actuarial model. The auditor''s independent estimate yields a range of $2.0 million to $2.8 million. Under AU-C 540 and AU-C 450, the auditor should:', '["Record a factual misstatement for the $400,000 difference between the point estimates", "Accept management''s estimate without further evaluation since it falls within the range", "Request management adjust the estimate to the midpoint of the auditor''s range", "Evaluate whether management''s point estimate within the range indicates possible bias toward a particular outcome"]'::jsonb, 3, 'AU-C 540.18 and AU-C 450.A9 require auditors to evaluate whether management''s point estimate, even when within an acceptable range, indicates potential bias. A $2.4 million estimate within a $2.0–$2.8 million range is reasonable but may reflect optimism or conservatism. Simply accepting the estimate without evaluating bias would be insufficient, as accumulated bias across multiple estimates could result in a material misstatement.', 'medium', 3),

-- Q13: medium / L3 — Key personnel turnover as deficiency indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westfield Corporation, the auditor notes that the controller, assistant controller, and chief accounting officer all resigned within a four-month period and were replaced by individuals with less experience. Under AU-C 265, the auditor should:', '["Evaluate whether the turnover and reduced experience represent a control deficiency affecting the entity''s ability to prepare reliable financial statements", "Document the turnover as an observation but take no further action since staffing is a management decision", "Immediately issue an adverse opinion due to lack of qualified accounting personnel", "Reduce planned reliance on controls but not report the turnover as a control deficiency"]'::jsonb, 0, 'AU-C 265.A7 identifies inadequate qualifications of accounting personnel as an indicator of a control deficiency. Rapid turnover and replacement with less experienced staff can diminish the entity''s ability to prepare reliable financial statements. While staffing decisions are management''s prerogative, the auditor must evaluate the financial reporting implications. This may rise to a significant deficiency or material weakness depending on the resulting control impact.', 'medium', 3),

-- Q14: easy / L1 — Written communication 60-day deadline
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, by when must the auditor communicate significant deficiencies and material weaknesses in writing?', '["Within 30 days of the audit report date", "No later than 60 days following the audit report release date", "Before the entity files its annual tax return", "Concurrent with the issuance of the management representation letter"]'::jsonb, 1, 'AU-C 265.13 requires written communication of significant deficiencies and material weaknesses to those charged with governance no later than 60 days following the release date of the auditor''s report. This timeline ensures timely governance awareness while allowing adequate time for the auditor to finalize evaluations. The 60-day deadline is distinct from any tax filing deadline or representation letter timing.', 'easy', 1),

-- Q15: medium / L2 — Absence of anti-fraud controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redwood Enterprises, the auditor determines that the company has no formal fraud risk assessment process and lacks a whistleblower hotline. Under AU-C 265 and AU-C 240, the absence of anti-fraud controls should be:', '["Ignored if no actual fraud has been detected during the audit", "Noted as a best-practice suggestion in a separate management letter only", "Evaluated as a potential control deficiency and communicated to those charged with governance", "Treated automatically as a material weakness requiring opinion modification"]'::jsonb, 2, 'AU-C 265.A12 indicates that the absence of controls to mitigate fraud risks may constitute a control deficiency. AU-C 240.35 requires the auditor to consider the entity''s anti-fraud programs and controls. The auditor evaluates whether the lack of fraud risk assessment and reporting mechanisms rises to a significant deficiency or material weakness. Not every absence constitutes a material weakness, but it must be communicated for governance consideration.', 'medium', 2),

-- Q16: hard / L4 — Restatement as material weakness indicator
(1, 'Misstatements and Control Deficiencies', 'Silverline Technologies restated its prior-year financial statements to correct a revenue recognition error totaling $3.2 million, which exceeded materiality. The restatement was identified by management, not by the auditor. During the current-year audit, the engagement partner evaluates whether the prior-year restatement indicates a material weakness. The most appropriate conclusion is that:', '["No material weakness exists because management self-identified and corrected the error", "The restatement is relevant only to the prior-year audit and has no effect on the current-year evaluation", "The restatement automatically constitutes a material weakness in the prior year but not the current year", "The need for restatement is a strong indicator of a material weakness, and the auditor should evaluate whether the underlying control deficiency has been remediated"]'::jsonb, 3, 'AU-C 265.A8 identifies restatement of previously issued financial statements as a strong indicator of a material weakness. The fact that management—rather than the auditor—discovered the error does not eliminate the inference that controls failed to prevent or detect the misstatement before the statements were originally issued. The current-year auditor must assess whether the root cause has been remediated or whether the weakness persists.', 'hard', 4),

-- Q17: medium / L2 — Communication of other deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'While auditing Lakeside Distribution, the auditor identifies several control deficiencies that do not rise to the level of significant deficiencies or material weaknesses. Under AU-C 265, the auditor''s responsibility regarding these other deficiencies is to:', '["Communicate them to management at an appropriate level of responsibility if the auditor determines they merit management''s attention", "Include them in the written communication to those charged with governance", "Disclose them in the auditor''s report as emphasis-of-matter paragraphs", "Document them only in the working papers without communicating them"]'::jsonb, 0, 'AU-C 265.11 requires the auditor to communicate in writing or orally to management deficiencies in internal control identified during the audit that are of sufficient importance to merit management''s attention but are not significant deficiencies or material weaknesses. This differs from the communication of significant deficiencies and material weaknesses, which must be in writing to those charged with governance under AU-C 265.12.', 'medium', 2),

-- Q18: medium / L3 — Misstatement effect on debt covenant compliance
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Freight, the auditor discovers a $60,000 understatement of operating expenses. Materiality is $250,000, but the company''s debt covenant requires a minimum current ratio of 2.0, and the entity''s current ratio is 2.05. Under AU-C 450, the auditor should:', '["Dismiss the misstatement as immaterial because it is below the $250,000 threshold", "Evaluate whether the misstatement, when corrected, could cause a violation of the debt covenant, making it material despite its small size", "Report the debt covenant to the lender without consulting management", "Reduce materiality to $60,000 for the remainder of the audit"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to consider whether uncorrected misstatements, individually or in aggregate, could cause the entity to fail to meet regulatory or contractual requirements such as debt covenants. A $60,000 correction could push the current ratio below 2.0, triggering a covenant violation. Evaluating misstatements solely against overall materiality without considering covenant implications would overlook a factor material to users'' decisions.', 'medium', 3),

-- Q19: medium / L2 — Documentation requirements for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Birchwood Services, the engagement team assembles the final documentation file. Under AU-C 450, the auditor''s working papers must include:', '["Only the list of misstatements that management agreed to correct", "A narrative explaining why each misstatement was judged to be immaterial", "The amount below which misstatements are regarded as clearly trivial, the summary of accumulated misstatements, and the auditor''s conclusion on whether uncorrected misstatements are material", "A separate opinion letter addressing each uncorrected misstatement individually"]'::jsonb, 2, 'AU-C 450.14 requires the auditor to document the clearly trivial threshold, all misstatements accumulated during the audit and whether they have been corrected, and the auditor''s conclusion about whether uncorrected misstatements individually or in aggregate are material to the financial statements. Documenting only corrected misstatements would fail to preserve the evaluation of items management chose not to correct.', 'medium', 2),

-- Q20: medium / L2 — Fraud vs error misstatement implications
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Medical Group, the auditor discovers that a billing clerk intentionally recorded fictitious patient charges totaling $18,000 and diverted the payments. Under AU-C 240 and AU-C 450, this misstatement should be treated differently from an unintentional error because:', '["Fraud misstatements are always material regardless of dollar amount", "Intentional misstatements are not included in the summary of uncorrected misstatements", "Errors require modification of the audit opinion while fraud does not", "The intentional nature affects the auditor''s evaluation of risk, the reliability of management representations, and potential implications for other audit areas"]'::jsonb, 3, 'AU-C 240.35-36 requires auditors to consider the implications of fraud on the audit, including reassessing risk, evaluating the integrity of management representations, and determining whether additional audit procedures are needed. Unlike an error, a fraud-related misstatement signals potential broader control failures and may indicate that other undetected misstatements exist. The dollar amount alone does not determine the significance of a fraud misstatement.', 'medium', 2),

-- Q21: easy / L1 — Misclassification misstatement definition
(1, 'Misstatements and Control Deficiencies', 'What type of misstatement occurs when a financial statement item is recorded in an incorrect account or category?', '["A misclassification misstatement", "A projected misstatement", "A factual misstatement", "A judgmental misstatement"]'::jsonb, 0, 'Under AU-C 450.A1, misclassification misstatements arise when items are presented or classified differently from what is required by the applicable financial reporting framework. Examples include classifying a long-term liability as current or reporting an operating expense as a capital expenditure. This differs from a factual misstatement, which is an error about which there is no doubt, such as an arithmetic or posting mistake.', 'easy', 1),

-- Q22: easy / L1 — Written communication form requirement
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what form must the auditor''s communication of material weaknesses to those charged with governance take?', '["Oral communication followed by written confirmation within 90 days", "Written communication", "Either oral or written at the auditor''s discretion", "Formal presentation to the full board of directors"]'::jsonb, 1, 'AU-C 265.12 explicitly requires that significant deficiencies and material weaknesses be communicated in writing to those charged with governance. Oral communication alone is insufficient for these higher-severity deficiencies, though oral communication may supplement the written report. The written requirement ensures there is a formal record for governance oversight and accountability.', 'easy', 1),

-- Q23: medium / L3 — Aggregate approaches materiality requiring action
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgecrest Industries, the aggregate of uncorrected misstatements totals $180,000 against a materiality level of $200,000. The auditor has completed all planned procedures. Under AU-C 450, the most appropriate response is to:', '["Issue an unmodified opinion since the aggregate does not exceed materiality", "Automatically issue a qualified opinion due to the proximity to materiality", "Request management to correct misstatements to reduce the aggregate, or perform additional procedures to determine whether additional misstatements exist", "Increase the materiality level to $250,000 to provide additional cushion"]'::jsonb, 2, 'AU-C 450.12 states that when the aggregate of uncorrected misstatements approaches materiality, the auditor considers whether there is a greater-than-remote likelihood that misstatements in the remaining untested population, combined with accumulated uncorrected misstatements, could exceed materiality. The auditor should encourage management to correct misstatements or expand procedures. Simply increasing materiality after the fact to accommodate findings would be inappropriate.', 'medium', 3),

-- Q24: easy / L2 — No requirement to search for deficiencies below significant
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Maple Grove Schools, the auditor identified two control deficiencies below the level of a significant deficiency. The engagement partner asks whether the auditor was required to identify all such deficiencies. Under AU-C 265, the auditor:', '["Must perform additional procedures to identify all control deficiencies regardless of severity", "Is required to design procedures specifically to search for deficiencies below the significant-deficiency level", "Must re-perform all tests of controls to ensure completeness of identified deficiencies", "Is not required to have identified all deficiencies less severe than a significant deficiency during the audit"]'::jsonb, 3, 'AU-C 265.09 states that the auditor is not required to perform procedures specifically to identify control deficiencies that are less severe than a significant deficiency. The auditor communicates those deficiencies that come to attention during the normal course of the audit and that merit management''s attention. Designing additional procedures solely to find lower-level deficiencies exceeds what the standard requires.', 'easy', 2),

-- Q25: hard / L4 — Compensating controls layered evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Whitfield Pharmaceuticals, the auditor discovers that the automated three-way match control in accounts payable was disabled for two months. However, the accounting supervisor performed daily manual review of all disbursements exceeding $5,000, and the internal audit team conducted a retrospective review of all transactions processed while the control was down. The auditor should evaluate this by:', '["Determining whether the compensating manual and internal audit procedures, in combination, adequately address the risk of misstatement during the period the automated control was inactive", "Classifying the disabled automated control as a material weakness regardless of compensating procedures", "Concluding that no deficiency exists because three layers of control operated at some point", "Testing only the automated control since it is the primary preventive control in the system"]'::jsonb, 0, 'AU-C 265.A5 requires the auditor to evaluate whether compensating controls mitigate the severity of a deficiency. The daily manual review and internal audit retrospective review may adequately cover the risk created by the disabled automated control, but the auditor must assess their effectiveness—including whether transactions below $5,000 were adequately monitored. Automatically classifying the deficiency as a material weakness without considering compensating controls would be an incomplete evaluation.', 'hard', 4),

-- Q26: easy / L1 — Tolerable misstatement purpose
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of tolerable misstatement in audit sampling?', '["To determine the tax liability for misclassified transactions", "To set the maximum misstatement in a population the auditor can accept and still conclude the sample results support the audit objective", "To calculate the penalty for management''s failure to correct errors", "To establish the fee structure for the audit engagement"]'::jsonb, 1, 'AU-C 530.05 defines tolerable misstatement as a monetary amount set by the auditor such that the auditor can obtain an appropriate level of assurance that actual misstatement in the population does not exceed that amount. It is typically set at or below performance materiality for the account balance being tested. This differs from overall materiality, which applies to the financial statements as a whole.', 'easy', 1),

-- Q27: hard / L4 — Disaggregation of misstatements by nature
(1, 'Misstatements and Control Deficiencies', 'During the audit of Continental Aerospace, the auditor accumulates these uncorrected misstatements: a $40,000 factual revenue overstatement, a $30,000 projected inventory understatement, and a $25,000 judgmental difference in the warranty reserve. Overall materiality is $120,000 and the simple sum is $95,000. The auditor should evaluate these by:', '["Adding the absolute values of all misstatements and comparing the total to materiality", "Netting all misstatements and concluding they are immaterial if the net falls below materiality", "Considering the nature and cause of each misstatement separately, evaluating whether netting is appropriate, and assessing the effect on specific line items and subtotals", "Excluding the projected misstatement because it is based on extrapolation rather than known facts"]'::jsonb, 2, 'AU-C 450.11 requires the auditor to consider whether uncorrected misstatements should be evaluated individually by nature (factual, judgmental, projected) and in relation to specific classes of transactions, account balances, and disclosures. Inappropriate netting—such as offsetting a revenue overstatement against an inventory understatement—could mask material misstatements in individual line items even when the aggregate appears immaterial.', 'hard', 4),

-- Q28: medium / L2 — Projecting sample misstatements to population
(1, 'Misstatements and Control Deficiencies', 'While auditing inventory at Coastal Hardware, the auditor tests a sample of 60 items from a population of 3,000 and finds a $6,200 pricing overstatement in the sample. Under AU-C 530, the auditor should:', '["Record only the $6,200 as a known misstatement without further extrapolation", "Conclude the population is misstated only if the error exceeds tolerable misstatement", "Request management to recount the entire inventory population", "Project the sample misstatement to the population and add the projected amount to the summary of uncorrected misstatements"]'::jsonb, 3, 'AU-C 530.13 requires the auditor to project misstatements found in the sample to the population. The $6,200 found in 60 items must be extrapolated to estimate the total likely misstatement across all 3,000 items. Recording only the known sample misstatement without projection would understate the likely population error. The projected misstatement is then added to the summary and evaluated along with other uncorrected misstatements.', 'medium', 2),

-- Q29: hard / L3 — Multiple deficiencies combining into material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Heritage Community Bank, the auditor identifies these individual control deficiencies: (1) loan officers can override credit limits without secondary approval, (2) the automated loan loss reserve calculation has not been validated in three years, and (3) monthly loan portfolio reconciliation is performed 45 days late. None individually constitutes a material weakness. Under AU-C 265, the auditor should:', '["Assess whether the combination of these deficiencies, considered together, creates a reasonable possibility that a material misstatement in the loan portfolio could go undetected", "Report each deficiency separately as a significant deficiency without combining them", "Conclude that since no individual deficiency is a material weakness, they need only be communicated as other deficiencies to management", "Evaluate only the deficiency with the largest potential dollar impact and disregard the others"]'::jsonb, 0, 'AU-C 265.A11 requires auditors to consider whether individual control deficiencies that are not material weaknesses on their own might combine to constitute a material weakness. These three loan-related deficiencies affect overlapping assertions and create compounding risk: overridden credit limits, an unvalidated reserve model, and delayed reconciliation all converge on the loan portfolio. Evaluating them in isolation would understate their collective severity.', 'hard', 3),

-- Q30: easy / L1 — Strong indicator of material weakness
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which of the following is identified as a strong indicator of a material weakness in internal control?', '["A change in the entity''s external auditor during the fiscal year", "Identification by the auditor of a material misstatement not initially detected by the entity''s internal controls", "The entity''s decision to outsource its payroll processing to a third-party provider", "A decline in the entity''s stock price during the audit period"]'::jsonb, 1, 'AU-C 265.A8 lists the identification of a material misstatement in the financial statements not initially identified by the entity''s internal control as a strong indicator of a material weakness. This demonstrates that controls failed in their fundamental purpose of preventing or detecting material misstatements. Changing auditors or outsourcing payroll does not in itself indicate a control weakness.', 'easy', 1)
;

COMMIT;
